/// 可換群 (Abelian Group)
///
/// Groupの全性質に加えて交換律を満たす
///
/// - 結合律: (a * b) * c = a * (b * c)
/// - 単位元: e * a = a * e = a
/// - 逆元: a * inverse(a) = inverse(a) * a = e
/// - 交換律: a * b = b * a
///
/// Rustの型システムで交換律を検証できないかも
/// 実装の方で丁寧にカバーしてみる
pub trait AbelianGroup: Group {}

/// クロージャで可換群を定義するための構造体
///
/// - identity: 単位元
