/// Union-Find
/// 経路圧縮とサイズによる併合を行う
/// root:      ほぼ O(α(N))
/// unite:     ほぼ O(α(N))
/// connected: ほぼ O(α(N))
pub struct UnionFind {
    // nodeの親、Noneの可能性があるのでOption
    pub parents: Vec<Option<usize>>,

    // 各集合のサイズ
    pub sizes: Vec<usize>,
} // end of struct

impl UnionFind {
    /// ノード数 n のUnionFind構築
    pub fn new(n: usize) -> Self {
        let parents = vec![None; n];
        let sizes = vec![1; n];
        return Self {
            parents,
            sizes,
        };
    } // end of constructor

    /// nodeに対する親を検索
    #[inline(always)]
    pub fn root(&mut self, node: usize) -> usize {
        // 親がいなければ自分が親
        if self.parents[node].is_none() {
            return node;
        }

        let parent = self.parents[node].unwrap();
        let root = self.root(parent);

        self.parents[node] = Some(root);
        return root;
    } // end of method

    /// u, v の所属する集合を結合
    #[inline(always)]
    pub fn unite(&mut self, u: usize, v: usize) {
        let mut ru = self.root(u);
        let mut rv = self.root(v);

        // 同じ集合なら何もなし
        if ru == rv {
            return;
        }

        // ruを小さい集合にする ru <= rvにする
        if self.sizes[ru] > self.sizes[rv] {
            std::mem::swap(&mut ru, &mut rv);
        }

        // 小さい集合を大きい集合につなぐ
        self.parents[ru] = Some(rv);

        // サイズ統合
        self.sizes[rv] += self.sizes[ru];
        self.sizes[ru] = self.sizes[rv];
        return;
    } // end of method

    /// 連結成分ごとの頂点リストを返す
    pub fn groups(&mut self) -> Vec<Vec<usize>> {
        let n = self.parents.len();

        // 根 -> Resの添字の対応
        let mut index = vec![usize::MAX; n];
        let mut res: Vec<Vec<usize>> = Vec::new();

        for node in 0..n {
            let root = self.root(node);
            // 新しい根なら新しい成分
            if index[root] == usize::MAX {
                index[root] = res.len();
                res.push(Vec::with_capacity(self.sizes[root]));
            }
            res[index[root]].push(node);
        }
        return res;
    } // end of method

    /// u, v が同じ集合に属しているかを返す
    #[inline(always)]
    pub fn connected(&mut self, u: usize, v: usize) -> bool {
        return self.root(u) == self.root(v);
    } // end of method

    // node が属する集合のサイズ
    #[inline(always)]
    pub fn size(&mut self, node: usize) -> usize {
        let root = self.root(node);
        return self.sizes[root];
    } // end of method
} // end of class

