// Library URL : https://github.com/fuyuki-yanagase/AtCoder_Utility_Rust/blob/fb6f94b1d523ce47f174b8f69c53a8d0a8698fa5/src/union_find.rs

/// 重み付きUnionFind
/// weights[v] = a[v] - a[parent[v]] (mod MOD)
/// root()による経路圧縮後は、根との差を保持する
pub struct WeightedUnionFind {
    pub parents: Vec<Option<usize>>,
    pub sizes: Vec<usize>,
    pub weights: Vec<i64>,
} // end of struct WeightedUnionFind

impl WeightedUnionFind {
    const MOD: i64 = 998244353;
    /// ノード数nで初期化
    pub fn new(n: usize) -> Self {
        return Self {
            parents: vec![None; n],
            sizes: vec![1_usize; n],
            weights: vec![0_i64; n],
        };
    } // end of constructor

    /// 根を取得し、経路圧縮と重みの更新
    #[inline(always)]
    pub fn root(&mut self, node: usize) -> usize {
        if let Some(parent) = self.parents[node] {
            let root = self.root(parent);

            // 親から根までの差を加える
            self.weights[node] = (self.weights[node] + self.weights[parent]) % Self::MOD;
            self.parents[node] = Some(root);
            return root;
        }
        return node;
    } // end of method

    /// a[node] - a[root]を取得
    #[inline(always)]
    pub fn weight(&mut self, node: usize) -> i64 {
        self.root(node);
        return self.weights[node];
    } // end of method

    /// a[u] - a[v] = x (mod MOD) を追加
    /// 矛盾しないならtrue
    /// 矛盾するならfalse (状態を変更しない)
    #[inline(always)]
    pub fn unite(&mut self, u: usize, v: usize, x: i64) -> bool {
        let mut ru = self.root(u);
        let mut rv = self.root(v);

        let wu = self.weights[u];
        let wv = self.weights[v];

        // 同じ集合なら既存の差と比較
        returnif!(ru == rv, (wu - wv).rem_euclid(Self::MOD) == x);

        // ruをrvにつなぐ場合に必要な重み
        // a[ru] - a[rv] = x - wu + wv;
        let mut w = (x - wu + wv).rem_euclid(Self::MOD);

        // サイズによる併合
        if self.sizes[ru] > self.sizes[rv] {
            std::mem::swap(&mut ru, &mut rv);
            // 接続方向が反転するので符号も反転
            w = (-w).rem_euclid(Self::MOD);
        }

        self.parents[ru] = Some(rv);
        self.weights[ru] = w;
        self.sizes[rv] += self.sizes[ru];

        return true;
    } // end of method

    /// a[u] - a[v]を取得
    /// 同じ集合に属していない場合はNone
    #[inline(always)]
    pub fn diff(&mut self, u: usize, v: usize) -> Option<i64> {
        let ru = self.root(u);
        let rv = self.root(v);
        returnif!(ru != rv, None);
        return Some((self.weights[u] - self.weights[v]).rem_euclid(Self::MOD));
    } // end of method

    /// 連結成分
    #[inline(always)]
    pub fn connected(&mut self, u: usize, v: usize) -> bool {
        return self.root(u) == self.root(v);
    } // end of method

    /// 集合のサイズ
    #[inline(always)]
    pub fn size(&mut self, node: usize) -> usize {
        let root = self.root(node);
        return self.sizes[root];
    } // end of method
} // end of impl WeightedUnionFind

