// Library URL : https://fuyuki-connect.net/libraries/rust/4f9d7e5464c603cf/src/union_find.rs
// Library URL : https://github.com/fuyuki-yanagase/AtCoder_Utility_Rust/blob/fb6f94b1d523ce47f174b8f69c53a8d0a8698fa5/src/union_find.rs

/// 群のポテンシャルを管理するUnionFind
/// 数学的定義
/// - 各頂点 v に未知の群要素 a[v] が割り当てられている
/// - weights[v] = inverse(a[parent[v]]) * a[v]
/// - root(v) 後は weights[v] = inverse(a[root(v)]) * a[v]
/// - unite(u, v, x) は a[u] = a[v] * x を追加
/// - diff(u, v) は inverse(a[v]) * a[u] を返す
///
/// * は Group::combine(left, right) の演算
/// 非可換群を扱うため、演算の順序を入れ替えられない
///
/// Group::S は Clone, PartialEq を要求
/// PartialEquは群として等しい要素を正しく比較できる前提
///
/// 各操作はサイズ併合と経路圧縮によって償却 O(α(N))
pub struct PotentialUnionFind<G>
where
    G: Group,
    G::S: Clone + PartialEq,
{
    /// 親ノード, 根はNone
    parents: Vec<Option<usize>>,

    /// 根が代表する連結成分の要素数
    sizes: Vec<usize>,

    /// 親を基準にしたポテンシャル
    /// 経路圧縮後は根を基準にしたポテンシャルに
    weights: Vec<G::S>,

    /// 群演算の実態, 設定値やクロージャを持つ群も扱えるはず
    group: G,
} // end of struct PotentialUnionFind<G>

impl<G> PotentialUnionFind<G>
where
    G: Group,
    G::S: Clone + PartialEq,
{
    /// n個のノードからなるUnionFind構築
    /// 最初は全て非連結、重みは単位元
    pub fn new(n: usize, group: G) -> Self {
        let identity = group.identity();

        return Self {
            parents: vec![None; n],
            sizes: vec![1; n],
            weights: vec![identity; n],
            group,
        };
    } // end of constructor

    /// nodeの根を取得
    ///
    /// 経路圧縮時に重みも更新
    /// a[node] = a[parent] * weights[node]
    /// a[parent] = a[root] * weights[parent]
    /// → a[node] = a[root] * weights[parent] * weights[node]
    #[inline(always)]
    pub fn root(&mut self, node: usize) -> usize {
        let Some(parent) = self.parents[node] else {
            return node;
        };
        let root = self.root(parent);

        // 非可換群なので必ず親の重みを左に
        // 再帰から戻った時点でweights[parent]は根から親への重み
        self.weights[node] = self.group.combine(&self.weights[parent], &self.weights[node]);
        self.parents[node] = Some(root);
        return root;
    } // end of method

    /// a[root(node)]^(-1) * a[node] を計算
    /// 根そのもののポテンシャルは単位元
    #[inline(always)]
    pub fn potential(&mut self, node: usize) -> G::S {
        self.root(node);
        return self.weights[node].clone();
    } // end of method

    /// a[u] = a[v] * x の制約を追加
    /// true: 既存の制約と矛盾しない
    /// false: 既存の制約と矛盾する。新たな制約は追加しない
    ///
    /// 同じ連結成分内で矛盾しない場合もtrue
    /// falseの場合でもroot()の経路圧縮は起こりうる
    #[inline(always)]
    pub fn unite(&mut self, u: usize, v: usize, x: G::S) -> bool {
        let ru = self.root(u);
        let rv = self.root(v);

        // すでに同じ成分なら現在の関係がxと一致するか
        // inverse(a[v]) * a[u] = inverse(weights[v]) * weights[u]
        if ru == rv {
            let inv_wv = self.group.inverse(&self.weights[v]);
            let actual = self.group.combine(&inv_wv, &self.weights[u]);
            return actual == x;
        }

        // ruをrvの子にする場合の重み
        // a[ru] * weights[u] = a[rv] * weights[v] * x
        // inverse(a[rv]) * a[ru] = weights[v] * x * inverse(weights[u])
        let vx = self.group.combine(&self.weights[v], &x);
        let inv_wu = self.group.inverse(&self.weights[u]);
        let ru_to_rv = self.group.combine(&vx, &inv_wu);

        // 小さい集合の根を大きい集合の根に繋ぐ
        if self.sizes[ru] <= self.sizes[rv] {
            // ruの新しい親はrv
            self.parents[ru] = Some(rv);
            self.weights[ru] = ru_to_rv;
            self.sizes[rv] += self.sizes[ru];
        } else {
            // rvの新しい親はru
            // 接続方向が逆なので重みも逆に
            self.parents[rv] = Some(ru);
            self.weights[rv] = self.group.inverse(&ru_to_rv);
            self.sizes[ru] += self.sizes[rv];
        }

        return true;
    } // end of method

    /// inverse(a[v]) * a[u] を取得
    /// 非連結で差が未確定ならNone
    /// 整数の加法群を使う場合は a[u] - a[v] に対応
    #[inline(always)]
    pub fn diff(&mut self, u: usize, v: usize) -> Option<G::S> {
        let ru = self.root(u);
        let rv = self.root(v);
        returnif!(ru != rv, None);

        // 順序に注意: inverse(weights[v]) * weights[u]
        let inv_wv = self.group.inverse(&self.weights[v]);
        return Some(self.group.combine(&inv_wv, &self.weights[u]));
    } // end of method

    /// 同じ集合に属するか
	#[rustfmt::skip]
	#[inline(always)]
    pub fn connected(&mut self, u: usize, v: usize) -> bool { self.root(u) == self.root(v) }

    /// nodeが属する集合の要素数
    #[inline(always)]
    pub fn size(&mut self, node: usize) -> usize {
        let root = self.root(node);
        return self.sizes[root];
    } // end of method

    /// 各連結成分の頂点リストを返す
    /// 頂点番号の昇順で走査、根ごとにグループ化
    pub fn groups(&mut self) -> Vec<Vec<usize>> {
        let n = self.parents.len();
        let mut root_to_index = vec![usize::MAX; n];
        let mut groups: Vec<Vec<usize>> = Vec::new();

        for node in 0..n {
            let root = self.root(node);
            if root_to_index[root] == usize::MAX {
                root_to_index[root] = groups.len();
                groups.push(Vec::with_capacity(self.sizes[root]));
            }
            groups[root_to_index[root]].push(node);
        }
        return groups;
    } // end of method
} // end of impl PotentialUnionFind<G>

// ======================================================================================
// ======================================================================================
// ======================================================================================
// ======================================================================================
//
//                                  区間並列 Union-Find
//
// ======================================================================================
// ======================================================================================
// ======================================================================================
// ======================================================================================
// Library URL : https://fuyuki-connect.net/libraries/rust/4f9d7e5464c603cf/src/union_find.rs
// Library URL : https://github.com/fuyuki-yanagase/AtCoder_Utility_Rust/blob/fb6f94b1d523ce47f174b8f69c53a8d0a8698fa5/src/union_find.rs

/// 区間 [a, a+k), [b, b+k) の対応する頂点同士をまとめて結合する。
///
/// 全体の計算量（コールバックの実行時間を除く）:
/// - 構築: O(N log N) 時間・空間。
/// - Q回の区間結合: 合計 O((N log N + Q) α(N)) 時間。
/// - root / connected / size: 償却 O(α(N)) 時間。
///
/// 同じ上位集合の区間では、対応する頂点がすべて連結済み。
/// 下位の結合を上位へ反映する必要はない（一方向の不変条件）。
///
/// ```
/// use utility_rust::union_find::RangeParallelUnionFind;
/// let mut uf = RangeParallelUnionFind::new(6);
/// assert_eq!(uf.unite_range(0, 3, 3), 3);
/// assert!(uf.connected(1, 4));
/// assert_eq!(uf.size(1), 2);
/// assert_eq!(uf.unite_range(0, 3, 3), 0);
/// ```
pub struct RangeParallelUnionFind {
    uf: UnionFind,
    // blocks[h-1][a] は長さ2^hの区間 [a, a+2^h) を表す。
    // 上位段は成分和などを持たないため、負のサイズ/親を1配列に圧縮する。
    blocks: Vec<Vec<isize>>,
} // end of struct RangeParallelUnionFind

impl RangeParallelUnionFind {
    /// 頂点数nで構築する。n = 0も許容する。
    pub fn new(n: usize) -> Self {
        let mut blocks = Vec::new();
        let mut len = 1;
        // 先にn/2と比較するため、倍化のオーバーフローは発生しない。
        while len <= n / 2 {
            len *= 2;
            blocks.push(vec![-1; n - len + 1]);
        }
        return Self {
            uf: UnionFind::new(n),
            blocks,
        };
    } // end of constructor

    /// u, vを結合する。実際に異なる成分を併合した場合にtrue。
    #[inline(always)]
    pub fn unite(&mut self, u: usize, v: usize) -> bool {
        return self.unite_range(u, v, 1) != 0;
    }

    /// 各i = 0..kについて、a+i, b+iを結合する。
    /// 戻り値は、元の頂点の連結成分を実際に併合した回数。
    #[inline(always)]
    pub fn unite_range(&mut self, a: usize, b: usize, k: usize) -> usize {
        return self.unite_range_with(a, b, k, |_, _| {});
    }

    /// 区間結合に伴い、元の頂点の成分を併合するたびにon_mergeを呼ぶ。
    /// 引数は(新しい根, 吸収された根)。呼び出し時点で併合は完了している。
    /// 同じ成分の再結合や上位段の併合ではコールバックを呼ばない。
    /// 呼び出し順は未規定。集計の更新は、このコールバック内で行う。
    /// 集計を維持する場合、すべての結合を同じ集計処理を渡して行うこと。
    ///
    /// a, b <= n かつ k <= min(n-a, n-b) が必要。
    /// k = 0ならa = n, b = nも許容する。
    /// 不正な区間では、結合を始める前にpanicする。
    #[inline(always)]
    pub fn unite_range_with<F>(&mut self, a: usize, b: usize, k: usize, mut on_merge: F) -> usize
    where
        F: FnMut(usize, usize),
    {
        let n = self.uf.parents.len();
        assert!(a <= n && b <= n && k <= n - a && k <= n - b, "区間が範囲外です");
        returnif!(k == 0 || a == b, 0);
        let h = (usize::BITS - 1 - k.leading_zeros()) as usize;
        let len = 1 << h;
        // 先頭と末尾の2冪長ブロックで全体を覆う。重複しても問題ない。
        let first = self.unite_block(h, a, b, &mut on_merge);
        let last = self.unite_block(h, a + k - len, b + k - len, &mut on_merge);
        return first + last;
    }

    /// nodeの属する成分の根。
    #[inline(always)]
    pub fn root(&mut self, node: usize) -> usize {
        return self.uf.root(node);
    }

    /// u, vが同じ連結成分に属するか。
    #[inline(always)]
    pub fn connected(&mut self, u: usize, v: usize) -> bool {
        return self.uf.connected(u, v);
    }

    /// nodeの属する連結成分の頂点数。
    #[inline(always)]
    pub fn size(&mut self, node: usize) -> usize {
        return self.uf.size(node);
    }

    /// 各連結成分の頂点リスト。O(N α(N))時間・O(N)追加空間。
    #[inline(always)]
    pub fn groups(&mut self) -> Vec<Vec<usize>> {
        return self.uf.groups();
    }

    #[inline(always)]
    fn block_root(parents: &mut [isize], node: usize) -> usize {
        returnif!(parents[node] < 0, node);
        let parent = parents[node] as usize;
        let root = Self::block_root(parents, parent);
        parents[node] = root as isize;
        return root;
    }

    #[inline(always)]
    fn unite_block<F>(&mut self, h: usize, a: usize, b: usize, on_merge: &mut F) -> usize
    where
        F: FnMut(usize, usize),
    {
        if h == 0 {
            let ra = self.uf.root(a);
            let rb = self.uf.root(b);
            returnif!(ra == rb, 0);
            self.uf.unite(ra, rb);
            let root = self.uf.root(ra);
            let absorbed = if root == ra { rb } else { ra };
            on_merge(root, absorbed);
            return 1;
        }

        let parents = &mut self.blocks[h - 1];
        let mut ra = Self::block_root(parents, a);
        let mut rb = Self::block_root(parents, b);
        returnif!(ra == rb, 0);
        if parents[ra] > parents[rb] {
            std::mem::swap(&mut ra, &mut rb);
        }

        let half = 1 << (h - 1);
        // 分割にはUnion-Findの根でなく、元の開始位置a, bを使う。
        let first = self.unite_block(h - 1, a, b, on_merge);
        let last = self.unite_block(h - 1, a + half, b + half, on_merge);

        // 子への伝播が完了してから記録する。
        // コールバックがpanicしても、未処理の区間を処理済みにしない。
        let parents = &mut self.blocks[h - 1];
        parents[ra] += parents[rb];
        parents[rb] = ra as isize;
        return first + last;
    }
} // end of impl RangeParallelUnionFind
